_CODE_RE = re.compile(r"```(?:python)?\s*(.*?)```", re.DOTALL)


def _extract_code(response: str, prompt: str) -> str:
    m = _CODE_RE.search(response)
    if m:
        return m.group(1).strip()
    lines = response.strip().splitlines()
